     "code": "from abc import ABC, abstractmethod\n\nclass Command(ABC):\n    @abstractmethod\n    def execute(self): pass\n    @abstractmethod\n    def undo(self): pass\n\nclass TextEditor:\n    def __init__(self):\n        self.text = \"\"\n    def __repr__(self):\n        return f\"'{self.text}'\"\n\nclass InsertCommand(Command):\n    def __init__(self, editor, text, position):\n        self.editor = editor\n        self.text_to_insert = text\n        self.position = position\n    \n    def execute(self):\n        self.editor.text = (self.editor.text[:self.position] + \n                           self.text_to_insert + \n                           self.editor.text[self.position:])\n    \n    def undo(self):\n        self.editor.text = (self.editor.text[:self.position] + \n                           self.editor.text[self.position + len(self.text_to_insert):])\n\nclass CommandHistory:\n    def __init__(self):\n        self.history = []\n    \n    def execute(self, cmd):\n        cmd.execute()\n        self.history.append(cmd)\n    \n    def undo(self):\n        if self.history:\n            self.history.pop().undo()\n\neditor = TextEditor()\nhistory = CommandHistory()\nhistory.execute(InsertCommand(editor, \"Hello\", 0))\nprint(editor)  # 'Hello'\nhistory.execute(InsertCommand(editor, \" World\", 5))\nprint(editor)  # 'Hello World'\nhistory.undo()\nprint(editor)  # 'Hello'",
