     "t": "code",
     "lang": "python",
     "code": "from abc import ABC, abstractmethod\n\nclass Handler(ABC):\n    def __init__(self):\n        self._next = None\n    \n    def set_next(self, handler):\n        self._next = handler\n        return handler\n    \n    def handle(self, request):\n        if self._next:\n            return self._next.handle(request)\n        return None\n\nclass AuthHandler(Handler):\n    def handle(self, request):\n        if not request.get(\"token\"):\n            return {\"status\": 401, \"error\": \"No token provided\"}\n        request[\"user\"] = {\"id\": 1, \"role\": \"admin\"}\n        return super().handle(request)\n\nclass RateLimitHandler(Handler):\n    def __init__(self):\n        super().__init__()\n        self.requests = {}\n    \n    def handle(self, request):\n        user_id = request.get(\"user\", {}).get(\"id\")\n        self.requests[user_id] = self.requests.get(user_id, 0) + 1\n        if self.requests[user_id] > 100:\n            return {\"status\": 429, \"error\": \"Rate limit exceeded\"}\n        return super().handle(request)\n\nclass ValidationHandler(Handler):\n    def handle(self, request):\n        if not request.get(\"body\"):\n            return {\"status\": 400, \"error\": \"Empty body\"}\n        return super().handle(request)\n\nclass BusinessHandler(Handler):\n    def handle(self, request):\n        return {\"status\": 200, \"data\": f\"Processed: {request['body']}\"}\n\nauth = AuthHandler()\nrate = RateLimitHandler()\nvalidate = ValidationHandler()\nbusiness = BusinessHandler()\n\nauth.set_next(rate).set_next(validate).set_next(business)\n\nprint(auth.handle({\"body\": \"data\"}))                    # 401 - no token\nprint(auth.handle({\"token\": \"abc\"}))                     # 400 - no body\nprint(auth.handle({\"token\": \"abc\", \"body\": \"hello\"}))   # 200 - success",
