     "code": "class ChatRoom:\n    def __init__(self):\n        self.users = {}\n    \n    def register(self, user):\n        self.users[user.name] = user\n        user.room = self\n    \n    def send(self, message, sender, recipient=None):\n        if recipient:\n            if recipient in self.users:\n                self.users[recipient].receive(message, sender)\n        else:\n            for name, user in self.users.items():\n                if name != sender:\n                    user.receive(message, sender)\n\nclass User:\n    def __init__(self, name):\n        self.name = name\n        self.room = None\n        self.messages = []\n    \n    def send(self, message, to=None):\n        print(f\"{self.name} sends: '{message}'\" + (f\" to {to}\" if to else \" (broadcast)\"))\n        self.room.send(message, self.name, to)\n    \n    def receive(self, message, sender):\n        msg = f\"[{sender} → {self.name}]: {message}\"\n        self.messages.append(msg)\n        print(f\"  {msg}\")\n\nroom = ChatRoom()\nalice = User(\"Alice\"); bob = User(\"Bob\"); charlie = User(\"Charlie\")\nroom.register(alice); room.register(bob); room.register(charlie)\n\nalice.send(\"Hello everyone!\")       # Broadcast\nbob.send(\"Hi Alice!\", \"Alice\")      # Direct message",
