     "code": "class TreeNode:\n    def __init__(self, val, left=None, right=None):\n        self.val = val\n        self.left = left\n        self.right = right\n\nclass InOrderIterator:\n    def __init__(self, root):\n        self.stack = []\n        self._push_left(root)\n    \n    def _push_left(self, node):\n        while node:\n            self.stack.append(node)\n            node = node.left\n    \n    def __iter__(self):\n        return self\n    \n    def __next__(self):\n        if not self.stack:\n            raise StopIteration\n        node = self.stack.pop()\n        self._push_left(node.right)\n        return node.val\n\nclass BFSIterator:\n    def __init__(self, root):\n        from collections import deque\n        self.queue = deque([root] if root else [])\n    \n    def __iter__(self):\n        return self\n    \n    def __next__(self):\n        if not self.queue:\n            raise StopIteration\n        node = self.queue.popleft()\n        if node.left: self.queue.append(node.left)\n        if node.right: self.queue.append(node.right)\n        return node.val\n\n#       4\n#      / \\\n#     2   6\n#    / \\ / \\\n#   1  3 5  7\ntree = TreeNode(4, TreeNode(2, TreeNode(1), TreeNode(3)),\n                   TreeNode(6, TreeNode(5), TreeNode(7)))\n\nprint(\"In-order:\", list(InOrderIterator(tree)))   # [1,2,3,4,5,6,7]\nprint(\"BFS:\", list(BFSIterator(tree)))             # [4,2,6,1,3,5,7]",
     "numbered": false
