     "code": "from abc import ABC, abstractmethod\n\nclass Specification(ABC):\n    @abstractmethod\n    def is_satisfied(self, item): pass\n    \n    def __and__(self, other):\n        return AndSpec(self, other)\n    \n    def __or__(self, other):\n        return OrSpec(self, other)\n    \n    def __invert__(self):\n        return NotSpec(self)\n\nclass AndSpec(Specification):\n    def __init__(self, *specs):\n        self.specs = specs\n    def is_satisfied(self, item):\n        return all(s.is_satisfied(item) for s in self.specs)\n\nclass OrSpec(Specification):\n    def __init__(self, *specs):\n        self.specs = specs\n    def is_satisfied(self, item):\n        return any(s.is_satisfied(item) for s in self.specs)\n\nclass NotSpec(Specification):\n    def __init__(self, spec):\n        self.spec = spec\n    def is_satisfied(self, item):\n        return not self.spec.is_satisfied(item)\n\nclass PriceBelow(Specification):\n    def __init__(self, max_price):\n        self.max_price = max_price\n    def is_satisfied(self, item):\n        return item[\"price\"] < self.max_price\n\nclass CategoryIs(Specification):\n    def __init__(self, category):\n        self.category = category\n    def is_satisfied(self, item):\n        return item[\"category\"] == self.category\n\nclass InStock(Specification):\n    def is_satisfied(self, item):\n        return item.get(\"stock\", 0) > 0\n\nproducts = [\n    {\"name\": \"Laptop\", \"price\": 999, \"category\": \"Electronics\", \"stock\": 5},\n    {\"name\": \"Book\", \"price\": 20, \"category\": \"Books\", \"stock\": 100},\n    {\"name\": \"Phone\", \"price\": 699, \"category\": \"Electronics\", \"stock\": 0},\n    {\"name\": \"Pen\", \"price\": 5, \"category\": \"Stationery\", \"stock\": 50},\n]\n\ncheap_electronics = PriceBelow(800) & CategoryIs(\"Electronics\") & InStock()\naffordable_available = PriceBelow(100) & InStock()\n\nfor spec_name, spec in [(\"Cheap electronics in stock\", cheap_electronics),\n                         (\"Affordable & available\", affordable_available)]:\n    matches = [p[\"name\"] for p in products if spec.is_satisfied(p)]\n    print(f\"{spec_name}: {matches}\")",
