     "t": "code",
     "lang": "python",
     "code": "class Entity:\n    def __init__(self, id=None, **kwargs):\n        self.id = id\n        for k, v in kwargs.items():\n            setattr(self, k, v)\n    def __repr__(self):\n        return f\"{self.__class__.__name__}(id={self.id})\"\n\nclass UnitOfWork:\n    def __init__(self):\n        self.new = []\n        self.dirty = []\n        self.removed = []\n    \n    def register_new(self, entity):\n        self.new.append(entity)\n    \n    def register_dirty(self, entity):\n        if entity not in self.dirty:\n            self.dirty.append(entity)\n    \n    def register_removed(self, entity):\n        self.removed.append(entity)\n    \n    def commit(self):\n        for entity in self.new:\n            print(f\"  INSERT: {entity}\")\n        for entity in self.dirty:\n            print(f\"  UPDATE: {entity}\")\n        for entity in self.removed:\n            print(f\"  DELETE: {entity}\")\n        self.new.clear()\n        self.dirty.clear()\n        self.removed.clear()\n    \n    def rollback(self):\n        self.new.clear()\n        self.dirty.clear()\n        self.removed.clear()\n        print(\"  ROLLBACK\")\n\nuow = UnitOfWork()\nuser = Entity(id=1, name=\"Alice\")\nuow.register_new(Entity(id=None, name=\"Bob\"))\nuow.register_dirty(user)\nuow.register_removed(Entity(id=3, name=\"Charlie\"))\nprint(\"Committing:\")\nuow.commit()",
