     "code": "class Event:\n    def __init__(self, type, data):\n        self.type = type\n        self.data = data\n\nclass WriteModel:\n    def __init__(self):\n        self.events = []\n    \n    def create_user(self, name, email):\n        event = Event(\"USER_CREATED\", {\"name\": name, \"email\": email})\n        self.events.append(event)\n        return event\n    \n    def update_user(self, email, **updates):\n        event = Event(\"USER_UPDATED\", {\"email\": email, **updates})\n        self.events.append(event)\n        return event\n\nclass ReadModel:\n    def __init__(self):\n        self.users = {}\n    \n    def apply(self, event):\n        if event.type == \"USER_CREATED\":\n            self.users[event.data[\"email\"]] = event.data.copy()\n        elif event.type == \"USER_UPDATED\":\n            email = event.data[\"email\"]\n            if email in self.users:\n                self.users[email].update(event.data)\n    \n    def get_user(self, email):\n        return self.users.get(email)\n    \n    def list_users(self):\n        return list(self.users.values())\n\n# Usage\nwrite = WriteModel()\nread = ReadModel()\n\ne1 = write.create_user(\"Alice\", \"alice@test.com\")\ne2 = write.create_user(\"Bob\", \"bob@test.com\")\ne3 = write.update_user(\"alice@test.com\", name=\"Alice Smith\")\n\n# Sync read model from events\nfor event in write.events:\n    read.apply(event)\n\nprint(read.get_user(\"alice@test.com\"))\nprint(read.list_users())",
