     "t": "code",
     "lang": "python",
     "code": "from abc import ABC, abstractmethod\n\nclass Plugin(ABC):\n    @property\n    @abstractmethod\n    def name(self): pass\n    \n    @abstractmethod\n    def execute(self, context): pass\n\nclass PluginManager:\n    def __init__(self):\n        self.plugins = {}\n        self.hooks = {}\n    \n    def register(self, plugin):\n        self.plugins[plugin.name] = plugin\n        print(f\"  Registered plugin: {plugin.name}\")\n    \n    def add_hook(self, hook_name, plugin_name):\n        self.hooks.setdefault(hook_name, []).append(plugin_name)\n    \n    def execute_hook(self, hook_name, context):\n        results = []\n        for plugin_name in self.hooks.get(hook_name, []):\n            plugin = self.plugins.get(plugin_name)\n            if plugin:\n                result = plugin.execute(context)\n                results.append((plugin_name, result))\n        return results\n\nclass LoggerPlugin(Plugin):\n    @property\n    def name(self): return \"logger\"\n    def execute(self, context):\n        msg = f\"Logged: {context.get('action', 'unknown')}\"\n        print(f\"    [Logger] {msg}\")\n        return msg\n\nclass ValidatorPlugin(Plugin):\n    @property\n    def name(self): return \"validator\"\n    def execute(self, context):\n        valid = bool(context.get(\"data\"))\n        print(f\"    [Validator] Valid: {valid}\")\n        return valid\n\nclass CachePlugin(Plugin):\n    @property\n    def name(self): return \"cache\"\n    def execute(self, context):\n        print(f\"    [Cache] Cached result for: {context.get('action')}\")\n        return True\n\nmanager = PluginManager()\nmanager.register(LoggerPlugin())\nmanager.register(ValidatorPlugin())\nmanager.register(CachePlugin())\n\nmanager.add_hook(\"before_save\", \"logger\")\nmanager.add_hook(\"before_save\", \"validator\")\nmanager.add_hook(\"after_save\", \"logger\")\nmanager.add_hook(\"after_save\", \"cache\")\n\nprint(\"\\nRunning 'before_save' hook:\")\nmanager.execute_hook(\"before_save\", {\"action\": \"create_user\", \"data\": {\"name\": \"Alice\"}})\nprint(\"\\nRunning 'after_save' hook:\")\nmanager.execute_hook(\"after_save\", {\"action\": \"create_user\"})",
