     "code": "import importlib\nfrom abc import ABC, abstractmethod\n\nclass Plugin(ABC):\n    @abstractmethod\n    def name(self): pass\n    @abstractmethod\n    def execute(self, data): pass\n\nclass UppercasePlugin(Plugin):\n    def name(self):\n        return \"uppercase\"\n    def execute(self, data):\n        return data.upper()\n\nclass ReversePlugin(Plugin):\n    def name(self):\n        return \"reverse\"\n    def execute(self, data):\n        return data[::-1]\n\nclass CountPlugin(Plugin):\n    def name(self):\n        return \"count\"\n    def execute(self, data):\n        return f\"{data} (length: {len(data)})\"\n\nclass PluginManager:\n    def __init__(self):\n        self._plugins = {}\n    \n    def register(self, plugin: Plugin):\n        self._plugins[plugin.name()] = plugin\n        print(f\"Registered plugin: {plugin.name()}\")\n    \n    def execute(self, plugin_name, data):\n        plugin = self._plugins.get(plugin_name)\n        if not plugin:\n            raise ValueError(f\"Plugin '{plugin_name}' not found\")\n        return plugin.execute(data)\n    \n    def execute_chain(self, plugin_names, data):\n        result = data\n        for name in plugin_names:\n            result = self.execute(name, result)\n        return result\n    \n    def list_plugins(self):\n        return list(self._plugins.keys())\n\npm = PluginManager()\npm.register(UppercasePlugin())\npm.register(ReversePlugin())\npm.register(CountPlugin())\n\nprint(pm.execute_chain([\"uppercase\", \"reverse\", \"count\"], \"hello\"))\n# Output: OLLEH (length: 5)",
